-- Normalize every question's category into the 12 canonical categories, and make
-- sure EACH of the 12 has real, topic-matching questions (so choosing a topic
-- never falls back to the mixed whole-bank).
--
-- The 12 canonical categories:
--   اطلاعات عمومی، فوتبال، سینما و سریال، علم و دانش، تاریخ ایران، موسیقی،
--   ایران و جهان، ورزش، هوش و معما، تکنولوژی، تاریخ جهان، مذهبی

-- 1) Broad mapping of the seed's primary categories → canonical.
UPDATE questions SET category = 'علم و دانش'     WHERE category IN ('علوم', 'سلامت', 'زیست‌شناسی', 'فیزیک', 'شیمی');
UPDATE questions SET category = 'ایران و جهان'   WHERE category IN ('جغرافیا', 'ایران');
UPDATE questions SET category = 'تکنولوژی'       WHERE category IN ('فناوری');
UPDATE questions SET category = 'تاریخ جهان'     WHERE category IN ('تاریخ');
UPDATE questions SET category = 'هوش و معما'     WHERE category IN ('ریاضی', 'هندسه');
UPDATE questions SET category = 'سینما و سریال'  WHERE category IN ('هنر', 'سرگرمی');
UPDATE questions SET category = 'اطلاعات عمومی'  WHERE category IN ('دانستنی', 'ادبیات', 'فرهنگ', 'اقتصاد');
-- ورزش already canonical.

-- 2) Catch-all: anything still outside the 12 → General Knowledge.
UPDATE questions SET category = 'اطلاعات عمومی'
WHERE category NOT IN (
  'اطلاعات عمومی','فوتبال','سینما و سریال','علم و دانش','تاریخ ایران','موسیقی',
  'ایران و جهان','ورزش','هوش و معما','تکنولوژی','تاریخ جهان','مذهبی'
);

-- 3) Refine sparse categories from the tag arrays (real matching content).
UPDATE questions SET category = 'فوتبال'      WHERE 'فوتبال' = ANY(tags);
UPDATE questions SET category = 'موسیقی'      WHERE 'موسیقی' = ANY(tags) OR 'کلاسیک' = ANY(tags);
UPDATE questions SET category = 'تاریخ ایران' WHERE ('ایران' = ANY(tags) AND ('تاریخ' = ANY(tags) OR 'هخامنشی' = ANY(tags)));

-- 4) Make the seeded questions queryable (seed used status='active').
UPDATE questions SET status = 'approved' WHERE status = 'active';

-- 5) Guarantee every sparse category has real, easy, on-topic questions.
--    Fixed UUIDs + ON CONFLICT DO NOTHING → safe to run more than once.
ON CONFLICT (id) DO NOTHING;
